scripts.紫轩对话.txt:
	If ($Event == 146) @Label2;
	If ($Event == 170) @Label1;
	Goto @end;
	
@Label1:
	If ($ZiXuanSense >> 20) @AddSenseEnd1;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd1:
	If ($Talkzixuan14 == 0) @Talk0;
	If ($Talkzixuan14 == 1) @Talk1;
	Say("紫轩：杨公子，时辰不早了，我们还是快点回芭蕉小筑吧。", 16);
	Goto @end; 
@Talk0:
	Say("杨影枫：紫轩，你经常独自一人到樱花谷吹萧吗？清平乡离樱花谷的路途可不近啊。", 2);
	Say("紫轩：……当我心情愁烦的时候，常喜欢一个人四处走走。自从无意中发现了樱花谷以后，我就爱上了那里的幽静。所以虽然路途遥远，我还是会常去那里吹萧，一段日子不去，我还会不习惯呢。", 17);
	Say("杨影枫：紫轩，原来你和我一样，都是寂寞的人……", 7);
	Assign($Talkzixuan14, 1);
	Goto @end;
@Talk1:
	Say("紫轩：杨公子，时辰不早了，我们还是快点回芭蕉小筑吧。", 16);
	Goto @end;
	

@Label2:
	If ($ZiXuanSense >> 20) @AddSenseEnd2;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd2:
	If ($Talkzixuan142 == 0) @Talk2;
	If ($Talkzixuan142 == 1) @Talk3;
	Return;
@Talk2:	
	Say("杨影枫：紫轩，你这么喜欢吹萧，是谁教你的？", 2);
	Say("紫轩：……", 20);
	Say("杨影枫：紫轩，你怎么哭啦？", 4);
	Say("紫轩：我…想起了我娘，是我娘教我的。", 20);	
	Say("杨影枫：（她这么伤心，要想一个什么法子让她开心才好。）", 2);
	Say("杨影枫：紫轩，惠安镇就在前面了，我听人说惠安镇醉仙楼里有一个唱歌的姑娘，歌声美妙无比，我们等会去听听吧？", 3);
	Say("紫轩：好吧。", 17);
	Assign($Talkzixuan142, 1);
	Return;
@Talk3:
	Say("杨影枫：据说惠安镇醉仙楼里的那个姑娘不仅歌唱得好，舞也跳的不错喔！", 3);
	Say("紫轩：是吗？", 16);
	Return;

@end:
	Return;

