scripts.月眉儿对话.txt:
StopMusic();
FadeOut();
PlayMusic("mc013.mp3");
ClearBody();
SetPlayerPos(15,54);
SetNpcPos("月眉儿",14,53);
Watch("杨影枫","月眉儿",0);
FadeIn();
Say("杨影枫：眉儿！你是怎么逃出来的？",4);
Say("月眉儿：我被关在飞龙堡的通天塔里，幸亏总管卢肇颢舍命把我救了出来，但是他却死在了通天塔里。", 24);
Say("杨影枫：你知道纳兰真和蔷薇的下落吗？",4);
Say("月眉儿：她们也被关在通天塔里，我本来想去救她们一起出来，但是通天塔守卫众多，高手如云，我只好先出来，没想到在这里见到了你。", 22);
Say("杨影枫：你的伤势要不要紧？",8);
Say("月眉儿：没关系，我们一起去飞龙堡救真儿她们吧！", 22);
Say("杨影枫：我看你伤得不轻，还是先去寒波谷养伤吧，紫轩正好也在寒波谷。",2);
Say("月眉儿：杨大哥，谢谢你救了我。", 22);
Say("杨影枫：眉儿，你不再恨我了吗？",2);
Say("月眉儿：……以前都怪我太任性，其实从第一次见到你，我就已经……", 123);
Say("杨影枫：眉儿，谢谢你能原谅我。",3);
Sleep(1000);
Say("月眉儿：好了，我不耽误你的时间了，你快去救人吧。", 22);
Say("杨影枫：眉儿，等着我回来。",2);
NpcGoto("月眉儿",9,44);
DelNpc("月眉儿");
SetMapTrap(1,"trap01.txt");
SetMapTrap(2,"trap02.txt");
SetMapTrap(3,"trap03.txt");
Assign($Event, 2008);
Memo("去飞龙堡救纳兰真和蔷薇。");
Return;

